static void __rpc_port_proxy_noti_setting_to(rpc_port_parcel_h parcel, void *data)
{
	rpc_port_proxy_noti_setting_h h = data;

	if (parcel == nullptr || h == nullptr) {
		_E("Invalid parameter");
		return;
	}

	rpc_port_parcel_write_string(parcel, STRING_GET(h->package_name));

	rpc_port_parcel_write_string(parcel, STRING_GET(h->app_id));

	rpc_port_parcel_write_bool(parcel, h->allow_to_notify);

	rpc_port_parcel_write_bool(parcel, h->do_not_disturb_except);

	rpc_port_parcel_write_bool(parcel, h->pop_up_notification);

	rpc_port_parcel_write_int32(parcel, h->visibility_class);

	rpc_port_parcel_write_int32(parcel, h->lock_screen_content_level);

	rpc_port_parcel_write_bool(parcel, h->app_disabled);
}

static void __rpc_port_proxy_noti_setting_from(rpc_port_parcel_h parcel, void *data)
{
	rpc_port_proxy_noti_setting_h h = data;

	if (parcel == nullptr || h == nullptr) {
		_E("Invalid parameter");
		set_last_result(RPC_PORT_ERROR_INVALID_PARAMETER);
		return;
	}

	rpc_port_parcel_read_string(parcel, &h->package_name);
	if (h->package_name == nullptr) {
		_E("Failed to read data");
		set_last_result(RPC_PORT_ERROR_OUT_OF_MEMORY);
		return;
	}

	rpc_port_parcel_read_string(parcel, &h->app_id);
	if (h->app_id == nullptr) {
		_E("Failed to read data");
		set_last_result(RPC_PORT_ERROR_OUT_OF_MEMORY);
		return;
	}

	rpc_port_parcel_read_bool(parcel, &h->allow_to_notify);

	rpc_port_parcel_read_bool(parcel, &h->do_not_disturb_except);

	rpc_port_parcel_read_bool(parcel, &h->pop_up_notification);

	rpc_port_parcel_read_int32(parcel, &h->visibility_class);

	rpc_port_parcel_read_int32(parcel, &h->lock_screen_content_level);

	rpc_port_parcel_read_bool(parcel, &h->app_disabled);

	set_last_result(RPC_PORT_ERROR_NONE);
}

int rpc_port_proxy_noti_setting_create(rpc_port_proxy_noti_setting_h *h)
{
	rpc_port_proxy_noti_setting_t *handle;

	if (h == nullptr) {
		_E("Invalid parameter");
		return RPC_PORT_ERROR_INVALID_PARAMETER;
	}

	handle = calloc(1, sizeof(rpc_port_proxy_noti_setting_t));
	if (handle == nullptr) {
		_E("Out of memory");
		return RPC_PORT_ERROR_OUT_OF_MEMORY;
	}

	handle->parcelable.to = __rpc_port_proxy_noti_setting_to;
	handle->parcelable.from = __rpc_port_proxy_noti_setting_from;

	*h = handle;

	return RPC_PORT_ERROR_NONE;
}

int rpc_port_proxy_noti_setting_destroy(rpc_port_proxy_noti_setting_h h)
{
	if (h == nullptr) {
		_E("Invalid parameter");
		return RPC_PORT_ERROR_INVALID_PARAMETER;
	}

	if (h->package_name)
		free(h->package_name);

	if (h->app_id)
		free(h->app_id);

	free(h);

	return RPC_PORT_ERROR_NONE;
}

int rpc_port_proxy_noti_setting_clone(rpc_port_proxy_noti_setting_h h, rpc_port_proxy_noti_setting_h *clone)
{
	rpc_port_proxy_noti_setting_h handle;
	rpc_port_parcel_h parcel;
	int ret;

	if (h == nullptr || clone == nullptr) {
		_E("Invalid parameter");
		return RPC_PORT_ERROR_INVALID_PARAMETER;
	}

	ret = rpc_port_proxy_noti_setting_create(&handle);
	if (ret != RPC_PORT_ERROR_NONE) {
		_E("Failed to create handle. error(%d)", ret);
		return ret;
	}

	ret = rpc_port_parcel_create(&parcel);
	if (ret != RPC_PORT_ERROR_NONE) {
		_E("Failed to create parcel handle. error(%d)", ret);
		rpc_port_proxy_noti_setting_destroy(handle);
		return ret;
	}

	rpc_port_parcel_write(parcel, &h->parcelable, h);
	rpc_port_parcel_read(parcel, &handle->parcelable, handle);
	ret = get_last_result();
	rpc_port_parcel_destroy(parcel);

	if (ret != RPC_PORT_ERROR_NONE) {
		_E("Failed to read data. error(%d)", ret);
		rpc_port_proxy_noti_setting_destroy(handle);
		return ret;
	}

	*clone = handle;

	return RPC_PORT_ERROR_NONE;
}
